namespace Zeta.Core;

/// <summary>
/// A bounded grow-only set view supporting capacity constraints and heat emissions.
/// </summary>
/// <remarks>
/// Laws:
/// - The no-forget policy rejects over-capacity additions through backpressure rather than evicting materialized elements.
/// - Forgetting policies report the forgotten finite-view loss as heat.
/// - Bounded union is idempotent and associative when both operands use the same projection policy.
/// </remarks>
public interface IBoundedGSet<T> : IGSet<T>
{
    /// <summary>The maximum capacity of the set.</summary>
    public int Capacity { get; }

    /// <summary>Whether the capacity has been reached.</summary>
    public bool IsSaturated { get; }
}

