namespace Zeta.Core;

/// <summary>
/// The DBSP incremental-dataflow operator set, mirrored from src/Core/DbspCellGraph.fs (the first CellScheduler consumer, 081KTG5S0M9). Operators exchange Z-set deltas as messages; each spans a DBSP tier — LINEAR (Filter/Rekey/Relay commute with the delta), NON-LINEAR (Distinct = the H operator, needs the integrated input), BILINEAR (Join = equi-join, weights multiply on key match), and the sink Integrate (running I). The load-bearing property is incremental ≡ recompute across the scheduler, and DoP-invariance. Anchor: Budiu et al. DBSP (VLDB 2023).
/// </summary>
/// <remarks>
/// Laws:
/// - Join is bilinear: (a+b) join c = (a join c) + (b join c). Cross-verified over weight arithmetic (weights multiply on key match, and multiplication distributes over addition).
/// - The sink integral folds deltas with Z-set addition, which is associative: (a+b)+c = a+(b+c).
/// - Z-set addition is commutative, so delta arrival order does not change the integral — the algebraic root of the scheduler's DoP-invariance for these operators.
/// - A retraction is the additive inverse: a + (-a) = 0. This is why an insert followed by its retraction cancels cleanly as it propagates through the graph.
/// - Filter(a+b) = Filter(a) + Filter(b). Documented (no scalar encoding — a Z-set-level law); proven in F#.
/// - Rekey(a+b) = Rekey(a) + Rekey(b). Documented (Z-set-level law); proven in F#.
/// - distinct(distinct(x)) = distinct(x) (set semantics). Documented (Z-set-level law); proven in F# via the integrated incremental form.
/// - For every operator: I(operator streamed over deltas) = operator(I(inputs)). The DBSP incremental-view-maintenance guarantee, holding ACROSS the cell scheduler. Documented (a whole-pipeline law, not a scalar identity); proven in F#.
/// - run(DoP=1) = run(DoP=N) for the operator graph — the scale-free law, holding for linear, non-linear, and bilinear operators alike. Documented (a scheduler-level law); proven in F#.
/// </remarks>
public interface IDbspOperators<TKey, TWeight>
{
    /// <summary>LINEAR selection: keep entries whose key satisfies the predicate; weight-independent, so Filter(a+b)=Filter(a)+Filter(b).</summary>
    public ZSet<TKey,TWeight> Filter(int parity, ZSet<TKey,TWeight> delta);

    /// <summary>LINEAR key-rewrite (projection): rewrite keys, preserve weights; distributes over Z-set addition.</summary>
    public ZSet<TKey,TWeight> Rekey(TKey factor, ZSet<TKey,TWeight> delta);

    /// <summary>LINEAR identity relay (a source/fan-out node): Relay(a)=a.</summary>
    public ZSet<TKey,TWeight> Relay(ZSet<TKey,TWeight> delta);

    /// <summary>NON-LINEAR set-semantics distinct (the DBSP H operator). Given the integrated input and a delta, emits only boundary-crossing (0<->positive) entries; work bounded by |delta|.</summary>
    public ZSet<TKey,TWeight> Distinct(ZSet<TKey,TWeight> integratedInput, ZSet<TKey,TWeight> delta);

    /// <summary>BILINEAR equi-join on the key: matched keys, weights multiplied. Incrementally, each side's delta joins the OTHER side's current integral, so I(out)=I(a) join I(b).</summary>
    public ZSet<TKey,TWeight> Join(ZSet<TKey,TWeight> leftIntegral, ZSet<TKey,TWeight> rightDelta);

    /// <summary>The sink's running integral I: acc' = acc + delta (Z-set addition).</summary>
    public ZSet<TKey,TWeight> Integrate(ZSet<TKey,TWeight> acc, ZSet<TKey,TWeight> delta);
}

