    /// <summary>The neutral element.</summary>
    public T Identity { get; }

    /// <summary>Associative binary operation.</summary>
    public T Combine(T a, T b);

    /// <summary>Group inverse: Combine(a, Inverse(a)) = Identity.</summary>
    public T Inverse(T a);
}

